// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime, address sender) public {
        // Admissible: sender not address(0), amount > 0 to cause meaningful overflow
        vm.assume(sender != address(0));
        vm.assume(amount > 0);
        // Bound amount to prevent huge values that make fuzzing inefficient
        amount = bound(amount, 1, type(uint256).max);

        // Record balance before Put
        uint256 contractBalanceBefore = address(c).balance;

        // Fund sender and call Put
        vm.deal(sender, amount);
        vm.prank(sender);
        c.Put{value: amount}(unlockTime);

        uint256 contractBalanceAfter = address(c).balance;
        // Sum of all Holders' balances (only sender has balance in this context)
        (uint256 accUnlockTime, uint256 accBalance) = c.Acc(sender);

        // The invariant: total balance tracked by contract equals its actual Ether
        assertTrue(accBalance == contractBalanceAfter - contractBalanceBefore);
    }
}

