pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlock1, uint256 unlock2, uint256 amount1, uint256 amount2, uint8 futureDelta) public {
        // Restrict amounts to avoid overflow in balance addition (the require in Put)
        vm.assume(amount1 < type(uint256).max / 2 && amount2 < type(uint256).max / 2);
        // Ensure unlock1 is after current block.timestamp by at least 1 second to be the dominant future time
        vm.assume(unlock1 > block.timestamp);
        // futureDelta ensures the second Put call's timestamp is also after the first one, so the max logic is testable
        vm.assume(futureDelta > 0);
        vm.warp(block.timestamp + uint256(futureDelta));
        // Derive unlock2 such that it is also in the future but less than unlock1,
        // so the expected final unlockTime remains unlock1 (the larger future time).
        unlock2 = unlock1 - 1;
        address sender = address(uint160(uint256(keccak256(abi.encode(unlock1, unlock2, amount1, amount2, futureDelta)))));
        vm.deal(sender, amount1 + amount2 + 1 ether);
        // First Put call with a large future unlock time
        vm.prank(sender);
        c.Put{value: amount1}(unlock1);
        // Advance time to ensure the second call's block.timestamp is still less than unlock1
        vm.warp(block.timestamp + 1);
        // Second Put call with a smaller future unlock time; the bug would set acc.unlockTime to block.timestamp
        vm.prank(sender);
        c.Put{value: amount2}(unlock2);
        // The correct contract preserves unlock1 as the maximum; the bug sets it to block.timestamp of the last call.
        (uint storedUnlockTime, ) = c.Acc(sender);
        assertTrue(storedUnlockTime == unlock1);
    }
}

