pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlock1, uint256 unlock2, uint256 amt1, uint256 amt2, uint256 fuzzAddrSeed) public {
        // Derive a deterministic sender address from the seed to avoid collisions and keep it wide.
        address sender = address(uint160(uint256(keccak256(abi.encode(fuzzAddrSeed)))));
        // Ensure we have enough balance for the two puts.
        vm.assume(amt1 <= type(uint128).max);
        vm.assume(amt2 <= type(uint128).max);
        vm.deal(sender, amt1 + amt2);

        // Bound unlock1 to be a future timestamp (strictly greater than current block.timestamp).
        // This ensures the first Put actually stores a meaningful future unlock time.
        uint256 nowTs = block.timestamp;
        unlock1 = bound(unlock1, nowTs + 1, type(uint256).max);
        // unlock2 is not constrained; it can be any value (even zero).

        // First Put with a future unlock time.
        vm.prank(sender);
        c.Put{value: amt1}(unlock1);

        // Second Put with a different (possibly smaller) unlock time.
        vm.prank(sender);
        c.Put{value: amt2}(unlock2);

        // General rule: after two Puts by the same sender, the stored unlockTime must equal the maximum
        // of the first supplied future unlock time and the block.timestamp of the second call (since
        // Put uses max(arg, block.timestamp) on each call). The bug always sets unlockTime to the block.timestamp
        // of the second call, ignoring the first future unlock time.
        (uint storedUnlock, ) = c.Acc(sender);
        assertTrue(storedUnlock == unlock1, "unlockTime should retain first future unlock time");
    }
}

