pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 pastTime, uint256 depositAmount, uint256 collectAmount) public {
        // Keep depositAmount above zero and at least 1 ether (MinSum) so Collect is possible
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount >= c.MinSum());
        // pastTime must be strictly less than current block.timestamp
        uint256 nowTime = block.timestamp;
        vm.assume(pastTime < nowTime);

        // Warp to a future time so block.timestamp > pastTime (necessary to test past unlock)
        vm.warp(nowTime + 100);
        uint256 futureNow = block.timestamp;

        // We need a fresh actor to avoid state pollution
        address actor = address(uint160(uint256(keccak256(abi.encode(pastTime, depositAmount, collectAmount)))));
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Put{value: depositAmount}(pastTime);

        // Now warp after pastTime, but before the Put's block.timestamp (which is futureNow for the reference)
        // For the reference, unlockTime = max(pastTime, block.timestamp at Put call) = futureNow.
        // For buggy, unlockTime = pastTime which is < futureNow.
        // We set time to futureNow + 50, which is > pastTime, so buggy's unlockTime is in the past, allowing Collect.
        // But reference's unlockTime is futureNow (still in future), so Collect should revert there.
        // Actually we want the opposite: reference should work, buggy should fail.
        // Let's rethink:
        // - Reference: unlockTime = futureNow (the time of Put). Collect requires block.timestamp > unlockTime.
        // - Buggy: unlockTime = pastTime. Collect requires block.timestamp > pastTime.
        // So if we warp to a time > futureNow, both satisfy. If we warp to a time between pastTime and futureNow,
        // buggy satisfies (pastTime) and reference does not (futureNow). This would make reference revert and buggy succeed.
        // We need the opposite: reference succeeds, buggy reverts.
        // That is impossible if we use the same actor and same state, because the condition is block.timestamp > unlockTime.
        // If unlockTime is smaller, Collect is more likely to succeed, not fail.
        // So the bug makes Collect succeed *earlier*, not fail. The original statement says "violating the invariant that Acc[msg.sender].unlockTime >= block.timestamp at the time of Put" but that's a trivial invariant.
        // The property we want: After a Put with a past timestamp, a subsequent Collect at a time *before* the original Put's timestamp should *fail* for the reference (still locked) but *succeed* for the buggy (past unlock). That's the opposite of our goal.
        // Wait: the problem statement says "after a call to Put(...) completes, the value of state variable Put differs: P.Put() != M.Put()" – that might mean the unlockTime value differs, which is true. But we need an assertion that passes on reference and fails on buggy.
        // Let's check: The reference sets unlockTime = max(_unlockTime, block.timestamp). The buggy sets unlockTime = _unlockTime.
        // So for _unlockTime < block.timestamp, reference unlockTime = block.timestamp, buggy unlockTime = _unlockTime.
        // Then if we call Put with a past _unlockTime, and then immediately try to Collect, the reference will revert (block.timestamp > unlockTime? block.timestamp == unlockTime? No, Collect requires block.timestamp > unlockTime, so if unlockTime == block.timestamp, Collect reverts). Buggy will also revert initially because block.timestamp > pastTime? block.timestamp is now, pastTime < now, so buggy unlockTime < now, so block.timestamp > unlockTime, so Collect would *succeed* for buggy! That means buggy succeeds, reference fails. Not what we want.
        // To get reference success and buggy failure, we need _unlockTime > block.timestamp? Then both set unlockTime = _unlockTime, no difference.
        // So there is no scenario where reference succeeds and buggy fails using the same inputs. The difference is only when _unlockTime < block.timestamp, where reference fails (locked until block.timestamp) but buggy succeeds (unlocked immediately).
        // The property "reference satisfies for every input and bug breaks for some input" must be framed as:
        // "It is impossible for a user to Collect their funds before the block.timestamp at the moment of their Put call."
        // For reference, this holds: unlockTime >= block.timestamp of Put, so collecting before that time fails.
        // For buggy, if _unlockTime < block.timestamp, unlockTime = _unlockTime < block.timestamp, so collecting immediately succeeds, violating the rule.
        // So the rule is: "After Put with a past _unlockTime, Collect must fail if block.timestamp <= block.timestamp at Put time." But block.timestamp at Put time is fixed. We can test by warping to a time after Put and checking if Collect succeeds.
        // Actually easier: after Put, the contract's invariant is that no Collect can happen before the max(_unlockTime, block.timestamp at Put). So we can assert that Collect reverts when time < that max.
        // But we can measure by calling Collect and checking revert.
        // We'll do: vm.warp to a time equal to block.timestamp of Put (so exactly at unlockTime for reference, but past for buggy). Buggy unlockTime = pastTime which is < block.timestamp at Put. So at that exact time, reference unlockTime == block.timestamp, so Collect reverts; buggy unlockTime < block.timestamp, so Collect succeeds.
        // So we assert that Collect reverts. reference reverts -> pass. buggy succeeds -> assert fails.
        // That works: assertFalse(collectSuccess) -> reference gives false, buggy gives true -> assertFalse(true) fails.
        // Let's do that.
        uint256 putTimestamp = block.timestamp; // this is futureNow after warp
        // We need to warp to exactly putTimestamp, because reference unlockTime = putTimestamp.
        // But block.timestamp can't be set exactly to a past time; we can only warp forward. So we need to structure so that the Put is called at a known timestamp, then we warp forward to that timestamp? That's impossible because warping forward increases time.
        // We can call Put at a time T, then warp to T + 1 (or some later time). Then reference unlockTime = T (if _unlockTime <= T). So at T+1, block.timestamp > T, so reference Collect should succeed! Wait, no: reference unlockTime = T. At T+1, block.timestamp = T+1 > T, so reference succeeds. Buggy unlockTime = pastTime (< T). At T+1, block.timestamp > pastTime, so buggy also succeeds. So both succeed? That's not a difference.
        // The difference is if we call Put at T with _unlockTime < T, then immediately (within same block) try Collect: block.timestamp = T. For reference, unlockTime = T, so Collect requires block.timestamp > T, fails. For buggy, unlockTime = _unlockTime < T, so block.timestamp > _unlockTime, succeeds.
        // That works! We can do Put and Collect in the same block, so block.timestamp remains T.
        // So we don't need warp for the test; we just need _unlockTime < block.timestamp, and then attempt Collect in the same block.
        // But we also need depositAmount >= MinSum, and Collect amount <= balance.
        collectAmount = bound(collectAmount, 1, depositAmount);
        uint256 time = block.timestamp;
        uint256 past = time - 1; // ensure past < time
        if (past == 0) past = 1; // avoid underflow if time=0
        vm.assume(past < time);

        // Deploy actor
        address actor2 = address(uint160(uint256(keccak256(abi.encode(past, depositAmount, collectAmount)))));
        vm.deal(actor2, depositAmount);
        vm.prank(actor2);
        c.Put{value: depositAmount}(past);

        // Try Collect immediately with same actor
        vm.prank(actor2);
        (bool ok,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        // For reference, Collect should fail (unlockTime == block.timestamp).
        // For buggy, Collect should succeed.
        assertTrue(!ok);
    }
}

