pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address account, uint256 pastTime, uint256 futureTime) public {
        // Ensure the past time is actually in the past relative to the current block
        vm.assume(pastTime < block.timestamp);
        // Ensure futureTime is truly in the future relative to the current block
        vm.assume(futureTime > block.timestamp);
        // Ensure account is not the zero address or the test contract
        vm.assume(account != address(0));
        vm.assume(account != address(this));

        // Set up the initial state: account makes a Put with a past time
        vm.prank(account);
        c.Put{value: 1}(pastTime);

        // Record the block.timestamp at the moment of the first Put
        uint256 put1Timestamp = block.timestamp;

        // Advance time so that block.timestamp is now greater than both pastTime and put1Timestamp
        // This ensures the difference in unlockTime behavior can be observed
        // We warp to a time that is strictly after put1Timestamp and also strictly after pastTime
        uint256 warpTo = put1Timestamp + 1 days;
        vm.warp(warpTo);

        // The account now makes a second Put call, this time with a futureTime, but with 0 value
        vm.prank(account);
        c.Put{value: 0}(futureTime);

        // After the second Put, the unlockTime must be at least the block.timestamp at the moment of that call.
        // The correct contract sets unlockTime to block.timestamp (since _unlockTime > block.timestamp is false for 0 value Put?
        // No, Put logic: _unlockTime>block.timestamp?_unlockTime:block.timestamp. Since futureTime > block.timestamp, it sets futureTime.
        // The buggy contract always sets _unlockTime, which is futureTime. So both set futureTime. This test needs to observe the difference caused by the first past Put.
        // Let's consider: the first Put with pastTime sets unlockTime to block.timestamp in correct, pastTime in buggy.
        // Then a zero-value Put with futureTime: correct sets futureTime, buggy sets futureTime. Both update to futureTime.
        // The difference would be if the second Put is also with a past time or with 0 value and a past time.
        // Let's modify the scenario: first Put with past time, then second Put with 0 value and a past time.
        // Correct: second Put sets unlockTime to block.timestamp (since past < block.timestamp). Buggy: sets past time.
        // So the unlockTime after second Put will be block.timestamp in correct, past in buggy.
        // This satisfies the rule: unlockTime must equal block.timestamp of the second Put call.

        // Redo: second Put with past time and 0 value.
        // We need a pastTime2 that is also in the past relative to the warped time.
        uint256 pastTime2 = warpTo - 1 hours;
        vm.assume(pastTime2 < block.timestamp);

        vm.prank(account);
        c.Put{value: 0}(pastTime2);

        uint256 unlockAfterSecondPut = c.Acc(account);
        // The correct contract should have set unlockTime to block.timestamp (since pastTime2 < block.timestamp)
        // The buggy contract sets unlockTime to pastTime2.
        // Assert that unlockTime == block.timestamp (the time of the second Put call)
        assertEq(unlockAfterSecondPut, block.timestamp);
    }
}

