pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTimeParam, uint256 msgValue, uint256 warpBlocks) public {
        // Keep msgValue reasonable to avoid overflow or running out of funds
        vm.assume(msgValue < type(uint128).max);
        // Warp to a well-defined timestamp so unlockTime comparisons are meaningful
        vm.roll(1);
        vm.warp(1 days + uint256(keccak256(abi.encode(warpBlocks))) % (365 days));
        uint256 currentTimestamp = block.timestamp;
        // Bound unlockTime param around current time so the fuzzer can explore both past and future times
        if (unlockTimeParam < currentTimestamp) {
            vm.assume(currentTimestamp - unlockTimeParam <= 365 days);
        } else {
            vm.assume(unlockTimeParam - currentTimestamp <= 365 days);
        }
        address caller = address(uint160(uint256(keccak256(abi.encode(msgValue, unlockTimeParam)))));
        vm.deal(caller, msgValue);
        vm.prank(caller);
        try c.Put{value: msgValue}(unlockTimeParam) {} catch {}
        // After Put, the unlockTime stored for the caller must be >= block.timestamp at the moment of the call
        uint256 storedUnlock = c.Acc(caller).unlockTime;
        assertTrue(storedUnlock >= currentTimestamp);
    }
}
